(function(){'use strict';const canvas=document.getElementById('ink-canvas');if(!canvas)return;const state={ctx:canvas.getContext('2d',{alpha:true}),width:0,height:0,dpr:1,blobs:[],raf:0,running:false,last:0,parallax:0.16,speed:0.45,count:7,scroll:0,calm:false,mode:'light'};const prefersReduced=window.matchMedia('(prefers-reduced-motion: reduce)');function readConfig(){const dataNode=document.getElementById('site-data');let cfg={};try{cfg=(JSON.parse((dataNode&&dataNode.textContent)||'{}').background)||{};}catch(e){cfg={};}
state.speed=typeof cfg.speed==='number'?cfg.speed:0.45;state.parallax=typeof cfg.parallax==='number'?cfg.parallax:0.16;state.count=Math.max(3,Math.min(12,cfg.blobs||7));state.style=cfg.style||'ink';if(cfg.style==='none')state.count=0;}
function palette(){const styles=getComputedStyle(document.documentElement);const dark=document.documentElement.getAttribute('data-mode')==='dark';return{ink:styles.getPropertyValue('--ink').trim()||(dark?'#ece7dd':'#1c1a17'),silver:styles.getPropertyValue('--silver').trim()||(dark?'#d8b56a':'#b08a3e'),dark};}
function hexToRgb(hex){const value=hex.replace('#','').trim();const full=value.length===3?value.split('').map((c)=>c+c).join(''):value;const num=parseInt(full||'000000',16);return{r:(num>>16)&255,g:(num>>8)&255,b:num&255};}
function rgba(rgb,alpha){return'rgba('+rgb.r+','+rgb.g+','+rgb.b+','+alpha.toFixed(3)+')';}
function resize(){const rect=canvas.getBoundingClientRect();state.dpr=Math.min(window.devicePixelRatio||1,1.5);state.width=Math.max(320,rect.width||window.innerWidth);state.height=Math.max(360,rect.height||window.innerHeight);canvas.width=Math.round(state.width*state.dpr);canvas.height=Math.round(state.height*state.dpr);state.ctx.setTransform(state.dpr,0,0,state.dpr,0,0);buildBlobs();}
function buildBlobs(){const colors=palette();const ink=hexToRgb(colors.ink);const silver=hexToRgb(colors.silver);const total=state.count;state.blobs=[];for(let i=0;i<total;i+=1){const useSilver=i%3===2;const radius=(0.16+Math.random()*0.22)*Math.max(state.width,state.height);state.blobs.push({baseX:Math.random(),baseY:Math.random(),radius:radius,ampX:0.05+Math.random()*0.1,ampY:0.04+Math.random()*0.09,speedX:(0.05+Math.random()*0.09)*(Math.random()<0.5?-1:1),speedY:(0.04+Math.random()*0.08)*(Math.random()<0.5?-1:1),phase:Math.random()*Math.PI*2,alpha:(useSilver?0.075:0.085)+Math.random()*0.06,color:useSilver?silver:ink});}}
function draw(time){const ctx=state.ctx;const colors=palette();ctx.clearRect(0,0,state.width,state.height);const base=ctx.createLinearGradient(0,0,0,state.height);const paperRgb=hexToRgb(colors.dark?'#0b0b0c':'#f7f7f8');base.addColorStop(0,rgba(paperRgb,0));base.addColorStop(1,rgba(paperRgb,colors.dark?0.35:0.5));ctx.fillStyle=base;ctx.fillRect(0,0,state.width,state.height);const t=time*0.00006*state.speed*60;state.blobs.forEach((blob)=>{const x=(blob.baseX+Math.sin(t*blob.speedX+blob.phase)*blob.ampX)*state.width;const y=(blob.baseY+Math.cos(t*blob.speedY+blob.phase)*blob.ampY)*state.height
-state.scroll*state.parallax;const gradient=ctx.createRadialGradient(x,y,0,x,y,blob.radius);const pulse=1+Math.sin(t*0.6+blob.phase)*0.08;gradient.addColorStop(0,rgba(blob.color,blob.alpha));gradient.addColorStop(0.45,rgba(blob.color,blob.alpha*0.42));gradient.addColorStop(1,rgba(blob.color,0));ctx.fillStyle=gradient;ctx.beginPath();ctx.arc(x,y,blob.radius*pulse,0,Math.PI*2);ctx.fill();});}
function loop(time){if(!state.running)return;if(time-state.last>33){state.last=time;draw(time);}
state.raf=requestAnimationFrame(loop);}
function start(){if(state.running||!state.count)return;state.running=true;state.raf=requestAnimationFrame(loop);}
function stop(){state.running=false;if(state.raf)cancelAnimationFrame(state.raf);state.raf=0;}
function applyCalm(){state.calm=document.documentElement.getAttribute('data-calm')==='on'||prefersReduced.matches;if(state.calm){stop();draw(performance.now());}else if(!document.hidden){start();}
canvas.style.opacity=state.calm?'0.28':'';}
document.addEventListener('DOMContentLoaded',()=>{readConfig();resize();applyCalm();if(!state.calm)start();let resizeTimer=0;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{resize();if(state.calm)draw(performance.now());},160);});window.addEventListener('scroll',()=>{state.scroll=window.scrollY;},{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();else if(!state.calm)start();});document.addEventListener('ink:reading',applyCalm);document.addEventListener('ink:mode',()=>{state.scroll=window.scrollY;if(state.calm)draw(performance.now());else buildBlobs();});if(prefersReduced&&prefersReduced.addEventListener)prefersReduced.addEventListener('change',applyCalm);});})();